/**
 * Database types for migrations that are written but not yet applied by Lovable (D-135).
 *
 * `src/integrations/supabase/types.ts` is regenerated by Lovable from the live database, so
 * anything added by an unapplied migration disappears from it. Code that uses those tables or
 * functions imports `db` from here instead of the plain client. Its type is the generated
 * schema plus the definitions below; at runtime it is the same Supabase client.
 *
 * When Lovable applies a migration, delete its section here (the generated types take over).
 * Pending: 0017_purge_audit_summary (no types), 0018_setup_governance, 0019_rollups (see roadmap.md).
 */
import type { SupabaseClient } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";
import type { Database, Json } from "@/integrations/supabase/types";

type Generated = Database["public"];

// Add types for a migration here while Lovable hasn't applied it yet; delete them once applied.
export type PendingEnums = Record<never, never>;
export type PendingTables = Record<never, never>;
export type PendingFunctions = {
  // 0018_setup_governance
  apply_setup_sections: { Args: Record<string, never>; Returns: string[] };
  // 0019_rollups
  org_rollup_members: {
    Args: { _org: string };
    Returns: {
      org_id: string;
      name: string;
      type: Generated["Enums"]["org_type"];
      parent_id: string | null;
      depth: number;
      profiles: number;
      good: number;
      grace: number;
      lapsed: number;
      pending: number;
      ended: number;
      no_membership: number;
      joined_30d: number;
      expiring_30: number;
      expiring_60: number;
      expiring_90: number;
    }[];
  };
  org_rollup_revenue: {
    Args: { _org: string; _from: string; _to: string };
    Returns: {
      org_id: string;
      name: string;
      depth: number;
      currency: string;
      payments: number;
      gross_minor: number;
      refunded_minor: number;
      net_minor: number;
    }[];
  };
  org_rollup_governance: {
    Args: { _org: string };
    Returns: {
      org_id: string;
      name: string;
      depth: number;
      required_seats: number;
      vacant_required: number;
      vacant_titles: string[];
      terms_past_end: number;
    }[];
  };
  log_report_export: {
    Args: { _org: string; _report: string; _row_count: number; _filter?: Json };
    Returns: undefined;
  };
};

export type FullDatabase = Omit<Database, "public"> & {
  public: {
    Tables: Omit<Generated["Tables"], keyof PendingTables> & PendingTables;
    Views: Generated["Views"];
    Functions: Omit<Generated["Functions"], keyof PendingFunctions> & PendingFunctions;
    Enums: Omit<Generated["Enums"], keyof PendingEnums> & PendingEnums;
    CompositeTypes: Generated["CompositeTypes"];
  };
};

/** The Supabase client, typed with pending migrations included. */
export const db = supabase as unknown as SupabaseClient<FullDatabase>;
